// AISHA Self-Deploy — Event-Driven
// Triggered by: postpublish hook, GitHub webhook, or manual POST

const input = $input.first().json || {};
const body = input.body || input;

const event = {
  source: body.source || body.action || 'unknown',
  version: body.version || (body.after ? body.after.slice(0,7) : 'latest'),
  repository: (body.repository && body.repository.full_name) || body.repository || 'evymo/aisha-dirigent',
  ref: body.ref || '',
  sender: (body.sender && body.sender.login) || body.sender || 'system',
  timestamp: new Date().toISOString()
};

// GitHub push — only react if it touches n8n-nodes-aisha
if (event.source === 'github' || body.ref) {
  const commits = body.commits || [];
  const touchesPackage = commits.some(c =>
    (c.added || []).concat(c.modified || [], c.removed || [])
      .some(f => f.startsWith('packages/n8n-nodes-aisha/'))
  );
  if (!touchesPackage && commits.length > 0) {
    event.skip = true;
    event.reason = 'Push does not touch n8n-nodes-aisha';
  }
}

return [{ json: event }];

// Compare Verdaccio latest vs installed (self-setup done marker)
const registry = $('Fetch Verdaccio').first().json;
const event = $('Parse Event').first().json;

const latest = (registry['dist-tags'] && registry['dist-tags'].latest) || 'unknown';
const publishedAt = (registry.time && registry.time[latest]) || 'unknown';
const allVersions = Object.keys(registry.versions || {});

let installed = 'unknown';
try {
  const fs = require('fs');
  installed = fs.readFileSync('/home/node/.n8n/.self-setup-done', 'utf-8').trim();
} catch { }

const needsUpdate = installed !== latest;

return [{ json: {
  event,
  installed,
  latest,
  publishedAt,
  needsUpdate,
  versionsAvailable: allVersions.length,
  timestamp: new Date().toISOString()
}}];

// Execute self-update:
//   1. npm install latest from Verdaccio
//   2. Delete done marker (forces re-provisioning)
//   3. Run self-setup.mjs synchronously

const { execSync } = require('child_process');
const fs = require('fs');

const prev = $json.installed;
const next = $json.latest;
const results = { steps: [], success: false };

try {
  // Step 1: Install update
  const installOut = execSync(
    'cd /home/node/.n8n/nodes && npm install n8n-nodes-aisha@latest --registry {{ $env?.NPM_REGISTRY_URL || '' }}/',
    { timeout: 60000, encoding: 'utf-8' }
  );
  results.steps.push({ step: 'npm_install', status: 'ok', output: installOut.slice(-200) });

  // Step 2: Delete done marker
  try { fs.unlinkSync('/home/node/.n8n/.self-setup-done'); } catch { }
  results.steps.push({ step: 'delete_marker', status: 'ok' });

  // Step 3: Run self-setup (re-provisions credentials, workflows, health)
  const setupOut = execSync(
    'AISHA_SKIP_SELF_UPDATE=1 node /home/node/.n8n/nodes/node_modules/n8n-nodes-aisha/bootstrap/self-setup.mjs',
    { timeout: 120000, encoding: 'utf-8' }
  );
  results.steps.push({ step: 'self_setup', status: 'ok', output: setupOut.slice(-500) });
  results.success = true;

} catch (err) {
  results.steps.push({ step: 'error', status: 'failed', message: err.message.slice(0, 300) });
}

return [{ json: {
  action: 'updated',
  previous: prev,
  current: next,
  ...results,
  timestamp: new Date().toISOString()
}}];

// Build event-driven report
const compare = $('Compare Versions').first().json || {};
const updateNode = $('Execute Update');
const update = updateNode.all().length > 0 ? updateNode.first().json : null;
const event = compare.event || {};

const lines = [
  '# AISHA Self-Deploy Report',
  '',
  '**Trigger:** ' + event.source + (event.sender ? ' (' + event.sender + ')' : ''),
  '**Timestamp:** ' + new Date().toISOString(),
  '',
  '**Installed:** v' + compare.installed,
  '**Latest (Verdaccio):** v' + compare.latest,
  '**Published:** ' + compare.publishedAt,
  ''
];

if (update) {
  lines.push('## Update: v' + update.previous + ' → v' + update.current);
  lines.push('');
  for (const step of update.steps || []) {
    const icon = step.status === 'ok' ? '✅' : '❌';
    lines.push('- ' + icon + ' **' + step.step + '**' + (step.message ? ': ' + step.message : ''));
  }
  lines.push('');
  lines.push(update.success ? '**Result: SUCCESS**' : '**Result: FAILED**');
} else {
  lines.push('## Already up-to-date');
  lines.push('');
  lines.push('No update needed.');
}

const severity = (update && !update.success) ? 'HIGH' : 'LOW';

return [{ json: {
  report: lines.join('\n'),
  severity,
  installed: compare.installed,
  latest: compare.latest,
  updated: !!update,
  success: update ? update.success : true
}}];

